import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function CustomerDashboard() {
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  const fetchUserProfile = async () => {
    const token = localStorage.getItem('token');
    if (!token) {
      setLoading(false);
      return;
    }

    try {
      const res = await axios.get('http://localhost:5000/api/auth/profile', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProfile(res.data);
    } catch (err) {
      console.error("Failed to fetch profile:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUserProfile();
  }, []);

  const handleCancelBooking = async (carId) => {
    const token = localStorage.getItem('token');
    if (!window.confirm("Are you sure you want to cancel this reservation?")) return;

    try {
      await axios.post('http://localhost:5000/api/auth/cancel-booking', { carId }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      alert("Reservation cancelled successfully!");
      fetchUserProfile(); // Refresh list automatically
    } catch (err) {
      alert(err.response?.data?.message || "Failed to cancel reservation.");
    }
  };

  if (loading) {
    return (
      <div className="max-w-4xl mx-auto py-16 px-6 text-center text-gray-500 font-semibold">
        Loading profile records...
      </div>
    );
  }

  const userData = profile?.user || profile;
  const bookedCars = profile?.bookedCars || [];

  // 🔍 Simple Filter: Only show cars that aren't marked available yet
  const activeBookings = bookedCars.filter(car => car && car.status !== 'available' && car.isAvailable !== true);

  return (
    <div className="max-w-5xl mx-auto py-12 px-6 space-y-8">
      {/* PROFILE HEAD */}
      <div className="bg-white border p-8 rounded-xl shadow-sm">
        <h1 className="text-3xl font-black text-neutral-900 uppercase tracking-tight mb-1">Customer Hub</h1>
        <p className="text-gray-500 text-sm">Welcome back, <span className="font-bold text-neutral-800">{userData?.name || 'Valued Client'}</span>.</p>
        <div className="mt-4 flex gap-6 text-xs text-gray-400 font-mono">
          <span>ID: {userData?._id}</span>
          <span>Email: {userData?.email}</span>
        </div>
      </div>

      {/* CAR LIST */}
      <div className="bg-white border rounded-xl shadow-sm overflow-hidden">
        <div className="p-6 border-b bg-gray-50/50">
          <h2 className="text-lg font-black text-neutral-900 uppercase tracking-tight">Your Reserved Fleet Vehicles</h2>
        </div>

        <div className="p-6">
          {activeBookings.length === 0 ? (
            <div className="border border-dashed border-gray-300 rounded-lg p-10 text-center bg-gray-50">
              <p className="text-gray-500 font-medium">You don't have any active rentals right now.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {activeBookings.map((car) => (
                <div key={car._id} className="border border-gray-200 rounded-xl overflow-hidden flex flex-col bg-white">
                  {car.image && (
                    <div className="h-44 bg-neutral-100 overflow-hidden border-b">
                      <img src={`http://localhost:5000${car.image}`} alt={car.model} className="w-full h-full object-cover" />
                    </div>
                  )}
                  
                  <div className="p-5 flex-1 flex flex-col justify-between space-y-4">
                    <div>
                      <h3 className="text-lg font-black text-neutral-900 uppercase tracking-tight">
                        {car.brand} <span className="text-neutral-500 font-medium text-base">{car.model}</span>
                      </h3>
                      <p className="text-xs text-gray-400 mt-1">ID: {car._id}</p>
                    </div>

                    <div className="border-t pt-4 flex justify-between items-center">
                      <span className="text-xs text-gray-400 font-mono">Status: Active</span>
                      <button
                        onClick={() => handleCancelBooking(car._id)}
                        className="px-4 py-2 rounded-lg text-xs font-bold uppercase bg-red-50 text-red-600 border border-red-200 hover:bg-red-600 hover:text-white transition-all duration-200"
                      >
                        Cancel Lease
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
